/** Institution logos embedded as data URIs.
 * GitHub's file API corrupts binary uploads (verified Oct 2026), so the two
 * collaboration logos are inlined here as base64. This module is imported only
 * by the lazy-loaded Collaboration page, keeping the initial bundle lean.
 * If the PNG files are ever uploaded to client/public/ properly, replace these
 * with "/bukhari-logo.png" and "/crescent-logo.png".
 * Frontend only: no logic changes. */
export const BUKHARI_LOGO_SRC = "data:image/png;base64,";
export const CRESCENT_LOGO_SRC = "data:image/png;base64,";
